#include <fstream>

using namespace std;

int main() {
    // Declare variables
    string line;
    int count = 0;

    // Open a text file
    ifstream myfile("file.txt");

    // Read each line from the file
    while (getline(myfile, line)) {
        // Split the line by any whitespace characters
        istringstream iss(line);
        string word;

        // Read a word from the stream
        while (iss >> word) {
            if (word == "word_to_count") {
                count++;
            }
        }
    }

    // Print the result
    cout << "Number of occurrences of 'word_to_count': " << count << endl;

    return 0;
}

