// Function to count occurrence of a word in a text file
void countOccurrences(string line, string word)
{
    std::stringstream ss(line);
    std::string word_str(word);
    int count = 0;
    while (std::getline(ss, line)) 
    {
        if(line.find(word_str) != std::string::npos)
            count++;
    }
    std::cout << "Number of occurrences of " << word << " in the text file is " << count << std::endl;
}

int main() 
{
    std::ifstream file("text.txt");
    // Read text file line by line
    std::string line;
    while (std::getline(file, line)) 
    {
        countOccurrences(line, "word");
    }
    return 0;
}

