#include <iostream>
#include <fstream>
#include <string>
#include <map>

// Function to count word occurrence in a file 
void countOccurrences(std::string word, std::ifstream& fin, std::map<std::string, int>& wordOccurence)
{
    std::string line;
    while (std::getline(fin, line))
    {
        std::string::size_type pos = line.find(word);
        if (pos != std::string::npos)
            wordOccurence[word]++;
    }
}

int main()
{
    // Declare variables
    std::string word = "myword";
    std::ifstream fin("file.txt");
    // Initialize word occurrence map
    std::map<std::string, int> wordOccurence = {
        {word, 0}
    };

    // Function to count word occurrence in a file
    countOccurrences(word, fin, wordOccurence);

    // Print the result
    std::map<std::string, int>::iterator wordIt = wordOccurence.find(word);
    std::cout << "Word: " << word << " occurred " << wordIt->second << " times in the file." << std::endl;

    return 0;
}

