def findCommonElements(arr1, arr2): 
    # create an empty dictionary to store common elements 
    common_elems = {} 

    # traverse arr1 and add elements to the dictionary 
    for i in arr1:
        if i in arr2:
            common_elems[i] = arr1.count(i)
        else:
            common_elems[i] = 0

    # traverse arr2 and update dictionary 
    for i in arr2:
        if i in common_elems:
            common_elems[i] += 1
        else:
            common_elems[i] = 1

    # return the common elements
    return common_elems.keys()
